import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
import hashlib
import hmac

app = Flask(__name__)

SECRET = os.environ.get('APP_SECRET', 'default-secret')
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def verify_signature(data, signature):
    """HMAC verification for internal API calls"""
    expected = hmac.new(SECRET.encode(), data.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_filename(filename):
    """Remove directory traversal attempts"""
    filename = filename.replace('..', '').replace('/', '').replace('\\', '')
    return filename

def get_extension(filename):
    if '.' in filename:
        return filename.rsplit('.', 1)[1].lower()
    return ''

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    ext = get_extension(uploaded.filename)
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension .{ext} not allowed'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    output_format = request.form.get('format', 'pdf')
    output_dir = tempfile.mkdtemp(prefix='convert_')

    # Convert using LibreOffice headless mode
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            text=True
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr}), 500

        output_name = safe_name.rsplit('.', 1)[0] + '.' + output_format
        output_path = os.path.join(output_dir, output_name)

        if os.path.exists(output_path):
            return send_file(output_path, as_attachment=True, download_name=output_name)
        else:
            return jsonify({'error': 'Output file not found'}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/thumbnail', methods=['POST'])
def generate_thumbnail():
    """Generate thumbnail for image files"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    ext = get_extension(uploaded.filename)
    if ext not in {'png', 'jpg', 'jpeg', 'gif'}:
        return jsonify({'error': 'Not an image file'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    size = request.form.get('size', '128x128')
    output_path = os.path.join(UPLOAD_DIR, f'thumb_{safe_name}')

    cmd = f'convert {input_path} -resize {size} {output_path}'
    subprocess.run(cmd, shell=True, capture_output=True, timeout=10)

    if os.path.exists(output_path):
        return send_file(output_path, as_attachment=True)
    return jsonify({'error': 'Thumbnail generation failed'}), 500

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
